  html, body { margin: 0; height: 100%; overflow: hidden; }
  /* Dusk fallback so the page is never white before or without WebGL. */
  body { background: linear-gradient(180deg, #1b1638 0%, #4b2b56 45%, #a04f52 72%, #f2a25c 100%); }
  #stage { position: fixed; inset: 0; }
  canvas { display: block; }
  .vignette {
    position: fixed; inset: 0; pointer-events: none;
    background: radial-gradient(ellipse at 50% 46%, transparent 55%, rgba(12, 8, 24, 0.42) 100%);
  }
  .caption {
    position: fixed; left: 26px; bottom: 22px; pointer-events: none;
    font-family: "Noto Serif JP", serif; color: #f4e3d0;
    text-shadow: 0 1px 8px rgba(20, 8, 30, 0.8);
    opacity: 0; transition: opacity 2.2s ease 0.6s;
    display: flex; align-items: baseline; gap: 14px;
  }
  .caption.show { opacity: 0.85; }
  .caption .jp { font-size: 26px; font-weight: 700; letter-spacing: 6px; }
  .caption .en { font-size: 11px; letter-spacing: 4px; opacity: 0.75; }
</style>
</head>
